files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --accent: #6c5ce7;
  --accent-hover: #7f6ff0;
  --accent-pressed: #5a4bd1;
  --border: #3d3d5c;
  --input-bg: #1e1e2f;
  --danger: #e74c3c;
  --success: #2ecc71;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 680px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 20px;
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

h2 {
  margin: 0 0 12px;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.items-section { margin-bottom: 28px; }

.line-items { display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }

.line-item {
  display: grid;
  grid-template-columns: 1fr 70px 90px 80px 36px;
  gap: 8px;
  align-items: center;
  padding: 10px;
  background: var(--bg);
  border-radius: 10px;
  border: 1px solid var(--border);
}

.line-item input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--input-bg);
  color: var(--text);
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.line-item input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.35);
}

.line-item input:hover { border-color: var(--accent-hover); }

.line-total {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  color: var(--success);
  font-size: 0.95rem;
  white-space: nowrap;
}

.btn {
  font-family: inherit;
  font-size: 0.95rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, box-shadow 0.15s;
}

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.5);
}

.btn-add {
  width: 100%;
  padding: 12px;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
}

.btn-add:hover { background: var(--accent-hover); }
.btn-add:active { background: var(--accent-pressed); transform: scale(0.99); }

.btn-remove {
  width: 36px;
  height: 36px;
  background: transparent;
  color: var(--danger);
  font-size: 1.2rem;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid transparent;
}

.btn-remove:hover { background: rgba(231, 76, 60, 0.15); border-color: var(--danger); }
.btn-remove:active { background: rgba(231, 76, 60, 0.3); }

.totals-section {
  border-top: 1px solid var(--border);
  padding-top: 20px;
}

.totals-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  font-size: 1rem;
}

.tax-row label { font-size: 1rem; }

.tax-row input {
  width: 90px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--input-bg);
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  text-align: right;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.tax-row input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.35);
}

.tax-row input:hover { border-color: var(--accent-hover); }

.grand-total {
  border-top: 2px solid var(--accent);
  margin-top: 8px;
  padding-top: 14px;
  font-size: 1.25rem;
  font-weight: 700;
}

.grand-total span:last-child { color: var(--success); }

#subtotal, #tax-amount, #grand-total {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

@media (max-width: 560px) {
  .line-item {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "desc desc"
      "qty price"
      "total remove";
  }
  .line-item .desc { grid-area: desc; }
  .line-item .qty { grid-area: qty; }
  .line-item .price { grid-area: price; }
  .line-item .line-total { grid-area: total; text-align: left; }
  .line-item .btn-remove { grid-area: remove; justify-self: end; }
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.3rem; }
}

(function () {
  'use strict';

  var lineItemsEl = document.getElementById('line-items');
  var addBtn = document.getElementById('add-item');
  var subtotalEl = document.getElementById('subtotal');
  var taxRateEl = document.getElementById('tax-rate');
  var taxAmountEl = document.getElementById('tax-amount');
  var grandTotalEl = document.getElementById('grand-total');

  function formatCurrency(value) {
    var n = Number(value);
    if (!isFinite(n)) n = 0;
    return '$' + n.toFixed(2);
  }

  function parseNumber(value) {
    var n = parseFloat(value);
    return isFinite(n) && n >= 0 ? n : 0;
  }

  function recalculate() {
    var rows = lineItemsEl.querySelectorAll('.line-item');
    var subtotal = 0;

    for (var i = 0; i < rows.length; i++) {
      var row = rows[i];
      var qty = parseNumber(row.querySelector('.qty').value);
      var price = parseNumber(row.querySelector('.price').value);
      var lineTotal = qty * price;
      subtotal += lineTotal;
      row.querySelector('.line-total').textContent = formatCurrency(lineTotal);
    }

    var taxRate = parseNumber(taxRateEl.value);
    var tax = subtotal * (taxRate / 100);
    var grand = subtotal + tax;

    subtotalEl.textContent = formatCurrency(subtotal);
    taxAmountEl.textContent = formatCurrency(tax);
    grandTotalEl.textContent = formatCurrency(grand);
  }

  function createLineItem() {
    var row = document.createElement('div');
    row.className = 'line-item';

    var descInput = document.createElement('input');
    descInput.type = 'text';
    descInput.className = 'desc';
    descInput.placeholder = 'Description';
    descInput.setAttribute('aria-label', 'Item description');

    var qtyInput = document.createElement('input');
    qtyInput.type = 'number';
    qtyInput.className = 'qty';
    qtyInput.min = '0';
    qtyInput.step = '1';
    qtyInput.value = '1';
    qtyInput.placeholder = 'Qty';
    qtyInput.setAttribute('aria-label', 'Quantity');

    var priceInput = document.createElement('input');
    priceInput.type = 'number';
    priceInput.className = 'price';
    priceInput.min = '0';
    priceInput.step = '0.01';
    priceInput.value = '0.00';
    priceInput.placeholder = 'Unit price';
    priceInput.setAttribute('aria-label', 'Unit price');

    var totalSpan = document.createElement('span');
    totalSpan.className = 'line-total';
    totalSpan.textContent = '$0.00';

    var removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'btn btn-remove';
    removeBtn.textContent = '\u00d7';
    removeBtn.setAttribute('aria-label', 'Remove line item');

    row.appendChild(descInput);
    row.appendChild(qtyInput);
    row.appendChild(priceInput);
    row.appendChild(totalSpan);
    row.appendChild(removeBtn);

    row.addEventListener('input', recalculate);
    removeBtn.addEventListener('click', function () {
      row.remove();
      recalculate();
    });

    lineItemsEl.appendChild(row);
    descInput.focus();
    recalculate();
  }

  addBtn.addEventListener('click', createLineItem);
  taxRateEl.addEventListener('input', recalculate);

  createLineItem();
})();
